// Příjem řádku z Arduina: validace podle protokolu, registr nodů (hello, hb, err) a rozdělení zpráv.
// Výstupy: 1 událost (ev), 2 vzorek teploty (m), 3 potvrzení povelu (ack), 4 povely pro node (obnova LED a LCD)
const gw = global.get("gw");
const S = global.get("state");
const now = Date.now();

const parsed = gw.parseLine(msg.payload);
if (!parsed.ok) {
  if (parsed.error !== "empty") {
    S.diag.badLines++;
    gw.pushError(S, "USB", `neplatný řádek: ${parsed.error}`);
  }
  return null;
}
const m = parsed.msg;
const nodeId = m.node ?? (m.id && m.id.includes(".") ? gw.nodeOfHwId(m.id) : S.lastNodeId ?? "node?");
const info = (S.nodes[nodeId] ??= { lastSeen: 0, up: null, devices: [], badDevices: [], lastSeq: null });
const wasOffline = !info.lastSeen || now - info.lastSeen > gw.NODE_OFFLINE_MS;
info.lastSeen = now;
S.lastNodeId = nodeId;

// mezera v seq = ztracený řádek; jen diagnostika, protokol zprávy neopakuje
if (Number.isInteger(m.seq)) {
  const gap = gw.seqGap(info.lastSeq, m.seq);
  if (info.lastSeq !== null && gap > 0 && gap < 1000) S.diag.lostMessages += gap;
  info.lastSeq = m.seq;
}

// Povely nastavují absolutní stav, opakované odeslání je bezpečné.
const reapplyOutputs = () => gw.nodeRestoreCommands(S, nodeId).map((c) => ({ topic: "send", payload: c }));

node.status({ fill: "green", shape: "dot", text: `${nodeId}: ${m.t}` });

switch (m.t) {
  case "hello":
    // hello posílá node po startu, výstupy je proto potřeba obnovit
    Object.assign(info, { devices: m.devices, badDevices: [], fw: m.fw, lastSeq: null });
    return [null, null, null, reapplyOutputs()];
  case "hb": {
    const restarted = info.up !== null && m.up < info.up; // uptime kleslo = restart nodu
    info.up = m.up;
    return [null, null, null, restarted || wasOffline ? reapplyOutputs() : null];
  }
  case "err":
    // vadný senzor se vyřadí z heartbeat, dokud nepřijdou platná data nebo nové hello
    if (m.id && m.id.includes(".") && !info.badDevices.includes(m.id)) info.badDevices.push(m.id);
    gw.pushError(S, nodeId, `${m.id ?? nodeId}: ${m.code}`);
    return null;
  case "ev":
  case "m":
    info.badDevices = info.badDevices.filter((d) => d !== m.id); // platná data = senzor funguje
    msg.payload = m;
    msg.receivedAt = now; // čas vzniku přiděluje gateway při přijetí
    return m.t === "ev" ? [msg, null, null, null] : [null, msg, null, null];
  case "ack":
    msg.topic = "ack";
    msg.payload = m;
    return [null, null, msg, null];
  default:
    return null;
}

// Každých 5 s: node bez zprávy 15 s je offline; když žádný node není online, požádá o ohlášení (who) –
// po otevření portu se Arduino restartuje a hello může přijít dřív, než gateway začne poslouchat.
const gw = global.get("gw");
const S = global.get("state");
const now = Date.now();

let online = 0;
for (const [id, n] of Object.entries(S.nodes)) {
  const isOnline = now - n.lastSeen <= gw.NODE_OFFLINE_MS;
  if (isOnline) online++;
  if (!isOnline && n.online === true) gw.pushError(S, id, "node je offline (15 s bez zprávy)");
  n.online = isOnline;
}

node.status({ fill: online ? "green" : "red", shape: "dot", text: `online nodů: ${online}` });
const lastWho = context.get("lastWho") ?? 0;
if (online === 0 && now - lastWho >= 15000) {
  context.set("lastWho", now);
  return { topic: "send", payload: { t: "who" } };
}
return null;

// Sériová fronta povelů pro node: přidělí cid, posílá po jednom, čeká na ack 500 ms a nejvýš 3× zopakuje.
// Vstup: topic "send" (payload = povel bez cid: led / reset / who) nebo "ack" (payload = ack z nodu).
// Výstup: řádek JSON pro uzel serial out (konec řádku přidá konfigurace portu).
const gw = global.get("gw");
const S = global.get("state");
const ACK_TIMEOUT_MS = 500;
const MAX_RETRIES = 3;
const MAX_QUEUE = 50;

const st = context.get("st") ?? { queue: [], active: null, counter: Math.floor(Math.random() * 100000) };
context.set("st", st);

function transmit() {
  const job = st.active;
  node.send({ payload: job.line });
  job.timer = setTimeout(onTimeout, ACK_TIMEOUT_MS);
}

function onTimeout() {
  const job = st.active;
  if (!job) return;
  if (job.attempts >= MAX_RETRIES) {
    // "who" bez odpovědi je běžné (node není připojený) – nehlásit jako chybu
    if (job.cmd.t !== "who") gw.pushError(S, "USB", `povel ${job.cmd.t} ${job.cmd.id ?? ""} bez potvrzení`);
    node.status({ fill: "red", shape: "ring", text: `bez ack: ${job.cmd.t}` });
    st.active = null;
    startNext();
    return;
  }
  job.attempts++;
  transmit();
}

function startNext() {
  if (st.active || !st.queue.length) return;
  st.active = st.queue.shift();
  transmit();
}

if (msg.topic === "ack") {
  const job = st.active;
  if (job && job.cid === msg.payload.cid) {
    clearTimeout(job.timer);
    if (msg.payload.ok === false) gw.pushError(S, "USB", `node odmítl ${job.cmd.t}: ${msg.payload.err ?? "?"}`);
    st.active = null;
    startNext();
  }
  return null;
}

// nový povel
st.counter = (st.counter + 1) % 100000000; // cid nejvýš 8 znaků
const cid = String(st.counter);
const line = gw.nodeCommandLine({ ...msg.payload, cid });
if (!line) {
  gw.pushError(S, "USB", "povel je delší než 128 B");
  return null;
}
if (st.queue.length >= MAX_QUEUE) st.queue.shift(); // nejstarší čekající povel zahodit (LED jsou absolutní stavy)
st.queue.push({ cid, cmd: msg.payload, line, attempts: 0, timer: null });
node.status({ fill: "green", shape: "dot", text: `${msg.payload.t} (cid ${cid}), ve frontě ${st.queue.length}` });
startNext();
return null;

finalize:
// [On Stop] Zastaví časovač čekání na ack.
const st = context.get("st");
if (st?.active?.timer) clearTimeout(st.active.timer);
context.set("st", undefined);

