// potvrzené položky → confirmed; výpadek / 5xx / 429 → nový pokus s rostoucím odstupem;
// 401/403 a chybná URL → alarm, data zůstávají; trvale odmítnutá data → dělení dávky a karanténa jedné položky.
const gw = global.get("gw");
const S = global.get("state");
const now = Date.now();
const { kind, items, full } = msg.batch;
const cls = gw.classifyResponse(msg.statusCode, msg.payload, msg.headers ?? {});
const seqs = (list) => gw.sqlList(list.map((i) => i.seq));
const retry = (item, delayMs, reason) =>
  `UPDATE outbox SET state = 'pending', nextAttemptAt = ${gw.lit(now + delayMs)}, lastError = ${gw.lit(reason)} WHERE seq = ${gw.lit(item.seq)}`;
const cloudState = (online, alarm) => {
  S.cloud.online = online;
  if (online) S.cloud.lastContactAt = new Date(now).toISOString();
  S.cloud.alarm = alarm;
};

const statements = [];
let more = false;
switch (cls.kind) {
  case "ok": {
    // potvrzené jsou jen položky, jejichž klíč je v accepted nebo duplicate seznamu
    const confirmed = gw.confirmedKeys(kind, msg.payload);
    const ok = items.filter((i) => confirmed.has(i.key));
    const rest = items.filter((i) => !confirmed.has(i.key));
    if (ok.length) statements.push(`UPDATE outbox SET state = 'confirmed', confirmedAt = ${gw.lit(now)}, lastError = NULL WHERE seq IN (${seqs(ok)})`);
    for (const i of rest) statements.push(retry(i, gw.backoffMs(i.attempts), "notConfirmed"));
    flow.set(`limit_${kind}`, gw.BATCH_SIZE);
    cloudState(true, null);
    more = full; // plná dávka → ve frontě je nejspíš další
    break;
  }
  case "retry":
    for (const i of items) statements.push(retry(i, gw.backoffMs(i.attempts), cls.reason));
    cloudState(false, null);
    break;
  case "rateLimited":
    for (const i of items) statements.push(retry(i, cls.retryAfterMs ?? gw.backoffMs(i.attempts), "429"));
    break;
  case "auth":
    for (const i of items) statements.push(retry(i, 60000, cls.reason));
    cloudState(true, `cloud odmítl token (${cls.reason}) – gateway smazaná nebo zablokovaná?`);
    break;
  case "serviceError":
    for (const i of items) statements.push(retry(i, 60000, cls.reason));
    cloudState(false, `neočekávaná odpověď (${cls.reason}) – zkontrolovat CLOUD_URL`);
    break;
  case "dataError":
    if (items.length > 1) {
      // dávka obsahuje vadnou položku: poslat znovu v pořadí po polovinách, dokud se neizoluje
      flow.set(`limit_${kind}`, Math.ceil(items.length / 2));
      statements.push(`UPDATE outbox SET state = 'pending', nextAttemptAt = 0 WHERE seq IN (${seqs(items)})`);
    } else {
      const error = JSON.stringify({ status: msg.statusCode, codes: cls.errorCodes });
      statements.push(`UPDATE outbox SET state = 'quarantined', lastError = ${gw.lit(error)} WHERE seq = ${gw.lit(items[0].seq)}`);
      gw.pushError(S, "cloud", `záznam v karanténě: ${cls.errorCodes.join(", ")}`);
      flow.set(`limit_${kind}`, gw.BATCH_SIZE);
    }
    more = true;
    cloudState(true, null);
    break;
}

node.status(cls.kind === "ok"
  ? { fill: "green", shape: "dot", text: `${kind}: potvrzeno ${items.length}` }
  : { fill: "yellow", shape: "ring", text: `${kind}: ${cls.kind} ${cls.reason ?? ""}` });
msg.topic = gw.transaction(statements);
msg.payload = null;
msg.more = more;
return msg;

// Konec odeslání: uvolní zámek; při plné dávce nebo izolaci vadné položky hned pokračuje další dávkou.
flow.set(`busy_${msg.batch.kind}`, 0);
return msg.more ? { payload: msg.batch.kind } : null;

// Cloudový heartbeat každých 30 s: úplný seznam právě dostupných zařízení a lokálně uložená revize
// konfigurace. Heartbeat se neukládá do fronty – po výpadku se posílá jen aktuální stav.
const gw = global.get("gw");
const S = global.get("state");
if (!S.ready || !S.identity?.token || !env.get("CLOUD_URL")) return null;
const body = {
  scenarioRevision: S.config?.scenario?.revision ?? 0, // 0 = gateway zatím nemá konfiguraci
  deviceList: gw.availableDevices(S.nodes, Date.now()),
};
return gw.cloudRequest(env.get("CLOUD_URL"), "POST", "/gateway/heartbeat", body, S.identity.token);

// Odpověď heartbeat: mapování hwId → deviceId, příznak změny konfigurace a počet čekajících povelů.
// Výstupy: 1 uložení mapování, 2 stáhnout konfiguraci, 3 doplnit mapování do fronty
const gw = global.get("gw");
const S = global.get("state");
const now = Date.now();
const cls = gw.classifyResponse(msg.statusCode, msg.payload, msg.headers ?? {});

if (cls.kind !== "ok") {
  S.cloud.online = cls.kind === "auth" || cls.kind === "dataError";
  S.cloud.alarm = cls.kind === "auth" ? "cloud odmítl token – gateway smazaná nebo zablokovaná?"
    : cls.kind === "dataError" ? `heartbeat odmítnut: ${cls.errorCodes.join(", ")}`
      : cls.kind === "serviceError" ? `neočekávaná odpověď (${cls.reason}) – zkontrolovat CLOUD_URL` : null;
  if (cls.kind === "dataError") gw.pushError(S, "heartbeat", cls.errorCodes.join(", "));
  node.status({ fill: "red", shape: "ring", text: `heartbeat: ${cls.reason ?? cls.kind}` });
  return null;
}

Object.assign(S.cloud, { online: true, lastContactAt: new Date(now).toISOString(), alarm: null, pendingCommands: msg.payload.pendingCommandCount });
let mappingChanged = false;
for (const d of msg.payload.deviceList ?? []) {
  if (S.deviceMap[d.hwId] !== d.id) {
    S.deviceMap[d.hwId] = d.id;
    mappingChanged = true;
  }
}
node.status({ fill: "green", shape: "dot", text: `OK, zařízení ${msg.payload.deviceList?.length ?? 0}${msg.payload.configChanged ? ", nová konfigurace" : ""}` });
return [
  mappingChanged ? { topic: gw.transaction([gw.kvUpsertSql("deviceMap", S.deviceMap, now)]) } : null,
  msg.payload.configChanged ? { payload: "configChanged" } : null,
  mappingChanged ? { payload: "mapping" } : null,
];

// Stažení konfigurace místnosti: při startu, při configChanged z heartbeat a tlačítkem na dashboardu.
const gw = global.get("gw");
const S = global.get("state");
if (!S.ready || !S.identity?.token || !env.get("CLOUD_URL")) return null;
return gw.cloudRequest(env.get("CLOUD_URL"), "GET", "/gateway/getConfig", null, S.identity.token);

// Uloží konfiguraci z cloudu jedním zápisem (při výpadku se použije poslední uložená kopie)
// a doplní mapování hwId → deviceId. Výstupy: 1 zápis do DB, 2 doplnit mapování ve frontě
const gw = global.get("gw");
const S = global.get("state");
const cls = gw.classifyResponse(msg.statusCode, msg.payload, msg.headers ?? {});
if (cls.kind !== "ok") {
  node.status({ fill: "red", shape: "ring", text: `getConfig: ${cls.reason ?? cls.kind}` });
  if (cls.kind === "auth") S.cloud.alarm = "cloud odmítl token – gateway smazaná nebo zablokovaná?";
  return null;
}
const now = Date.now();
const { uuAppErrorMap, ...config } = msg.payload;
S.config = config;
for (const d of config.deviceList ?? []) S.deviceMap[d.hwId] = d.id;
const statements = [gw.kvUpsertSql("config", config, now), gw.kvUpsertSql("deviceMap", S.deviceMap, now)];

// stav hry z cloudu převezme jen tehdy, když žádný místní nemá – novější místní stav nepřepisuje
if (!S.game && config.currentGame) {
  S.game = gw.gameFromSnapshot(config.currentGame);
  statements.push(gw.kvUpsertSql("game", S.game, now));
}
node.status({ fill: "green", shape: "dot", text: `revize ${config.scenario?.revision}, zařízení ${config.deviceList?.length ?? 0}` });
return [{ topic: gw.transaction(statements) }, { payload: "mapping" }];

// Položky fronty, které čekají na cloudové deviceId (vznikly dřív, než heartbeat zařízení zaregistroval).
msg.topic = "SELECT seq, hwId, payload FROM outbox WHERE state = 'waitingMapping' ORDER BY seq LIMIT 500";
msg.payload = [];
return msg;

// Doplní deviceId do čekajících položek a uvolní je k odeslání. UUID a čas vzniku se zachovají;
// položka ještě nebyla odeslána, takže doplnění payloadu je v pořádku.
const gw = global.get("gw");
const S = global.get("state");
const statements = [];
for (const row of msg.payload ?? []) {
  const deviceId = S.deviceMap[row.hwId];
  if (!deviceId) continue;
  const payload = { ...JSON.parse(row.payload), deviceId };
  statements.push(`UPDATE outbox SET payload = ${gw.lit(JSON.stringify(payload))}, state = 'pending' WHERE seq = ${gw.lit(row.seq)} AND state = 'waitingMapping'`);
}
if (!statements.length) return null;
node.status({ fill: "green", shape: "dot", text: `doplněno mapování: ${statements.length}` });
msg.topic = gw.transaction(statements);
return msg;

// Každé 2 s vyzvedne čekající povely z cloudu (gateway/getCommands). Další dotaz až po dokončení předchozího.
const gw = global.get("gw");
const S = global.get("state");
if (!S.ready || !S.identity?.token || !env.get("CLOUD_URL")) return null;
const busy = flow.get("busy_commands");
if (busy && Date.now() - busy < 30000) return null;
flow.set("busy_commands", Date.now());
return gw.cloudRequest(env.get("CLOUD_URL"), "GET", "/gateway/getCommands?limit=100", null, S.identity.token);

// Nové povely nejdřív trvale uloží do command_log (stejné commandId se nevloží dvakrát).
// Výstupy: 1 zápis nových povelů, 2 žádné nové povely → rovnou dotaz na povely k provedení
const gw = global.get("gw");
const S = global.get("state");
const cls = gw.classifyResponse(msg.statusCode, msg.payload, msg.headers ?? {});
if (cls.kind !== "ok") {
  flow.set("busy_commands", 0);
  node.status({ fill: "red", shape: "ring", text: `getCommands: ${cls.reason ?? cls.kind}` });
  return null;
}
const items = msg.payload.itemList ?? [];
if (!items.length) return [null, { payload: [] }];
const now = Date.now();
const statements = items.map((c) =>
  `INSERT OR IGNORE INTO command_log (commandId, type, payload, createdAt, state, receivedAt) VALUES ` +
  `(${gw.lit(c.id)}, ${gw.lit(c.type)}, ${gw.lit(JSON.stringify(c.payload ?? {}))}, ${gw.lit(c.createdAt)}, 'received', ${gw.lit(now)})`);
node.status({ fill: "blue", shape: "dot", text: `přijato povelů: ${items.length}` });
return [{ topic: gw.transaction(statements) }, null];

// Povely k provedení (received) a provedené, ale v cloudu zatím nepotvrzené (executed), v pořadí cloudu.
msg.topic = "SELECT commandId, type, payload, state FROM command_log WHERE state IN ('received', 'executed') ORDER BY createdAt, commandId";
msg.payload = [];
return msg;

// Provede přijaté povely v pořadí cloudu nad místním stavem hry. Povel, který čeká na novou konfiguraci,
// zastaví zpracování – novější povel ho nepředběhne. Již provedené povely se neopakují, jen se potvrdí.
// Výstupy: 1 zápis do DB, 2 nic k zápisu → rovnou potvrzení, 3 stáhnout konfiguraci
const gw = global.get("gw");
const S = global.get("state");
const now = Date.now();
const nowIso = new Date(now).toISOString();

const statements = [];
const serial = [];
const ackIds = [];
let needConfig = false;
for (const row of msg.payload ?? []) {
  if (row.state === "executed") { ackIds.push(row.commandId); continue; }
  const command = { type: row.type, payload: JSON.parse(row.payload) };
  const result = gw.applyCommand({ config: S.config, game: S.game, command, nowIso });
  if (result.needConfig) { needConfig = true; break; }
  S.game = result.game;
  if (result.resetNodes) {
    S.leds = {};
    S.displays = {};
    serial.push({ topic: "send", payload: { t: "reset" } }); // node zhasne LED, smaže LCD a vynuluje stav
  }
  for (const c of gw.outputCommandsFor(S, result.outputActions, now, statements)) serial.push({ topic: "send", payload: c });
  statements.push(`UPDATE command_log SET state = 'executed', executedAt = ${gw.lit(now)} WHERE commandId = ${gw.lit(row.commandId)}`);
  ackIds.push(row.commandId);
  node.status({ fill: "blue", shape: "dot", text: `${command.type} → hra ${S.game?.state ?? "–"}` });
}
if (statements.length) {
  statements.push(gw.kvUpsertSql("game", S.game, now), gw.kvUpsertSql("leds", S.leds, now), gw.kvUpsertSql("displays", S.displays ?? {}, now));
}

const out = { ackIds, serial };
return [
  statements.length ? { ...out, topic: gw.transaction(statements) } : null,
  statements.length ? null : out,
  needConfig ? { payload: "resetRoom" } : null,
];

// Po zápisu: pošle povely nodu (LED, reset) a potvrdí provedené povely v cloudu (gateway/ackCommands).
// Výstupy: 1 povely pro node, 2 HTTP požadavek ackCommands
const gw = global.get("gw");
const S = global.get("state");
const ackIds = (msg.ackIds ?? []).slice(0, 100);
if (!ackIds.length || !S.identity?.token) {
  flow.set("busy_commands", 0);
  return [msg.serial ?? [], null];
}
const request = gw.cloudRequest(env.get("CLOUD_URL"), "POST", "/gateway/ackCommands", { commandIdList: ackIds }, S.identity.token);
return [msg.serial ?? [], { ...request, ackIds }];

// Výsledek potvrzení povelů. Při ztracené odpovědi se opakuje jen potvrzení, akce se neprovádí znovu.
// Povel, který cloud už nezná (retence 7 dní), se vyřadí z opakování a zapíše se do diagnostiky.
const gw = global.get("gw");
const S = global.get("state");
const cls = gw.classifyResponse(msg.statusCode, msg.payload, msg.headers ?? {});
const now = Date.now();
let ids = [];
let note = null;
if (cls.kind === "ok") {
  ids = msg.payload.acknowledgedCommandIdList ?? [];
} else if (cls.kind === "dataError" && cls.errorCodes.some((c) => c.endsWith("/gatewayCommandDoesNotExist"))) {
  const entry = Object.values(msg.payload.uuAppErrorMap).find((e) => e.type === "error");
  ids = entry?.paramMap?.commandIdList ?? [];
  note = "unknownInCloud";
  gw.pushError(S, "povely", `cloud nezná povely: ${ids.join(", ")}`);
}
if (!ids.length) {
  flow.set("busy_commands", 0);
  return null;
}
msg.topic = gw.transaction([
  `UPDATE command_log SET state = 'confirmed', confirmedAt = ${gw.lit(now)}, lastError = ${gw.lit(note)} WHERE commandId IN (${gw.sqlList(ids)})`,
]);
return msg;

// Konec kola povelů: uvolní zámek pro další vyzvednutí.
flow.set("busy_commands", 0);
return null;

// Registrace gateway jednorázovým kódem (dashboard nebo REGISTRATION_CODE). Kód se neukládá ani neloguje.
const gw = global.get("gw");
const S = global.get("state");
const code = String(msg.payload?.code ?? "").trim();
if (!code) return null;
if (!env.get("CLOUD_URL")) {
  S.registration = { ok: false, message: "chybí CLOUD_URL" };
  return null;
}
if (S.identity?.token) {
  S.registration = { ok: false, message: "gateway už je registrovaná" };
  return null;
}
node.status({ fill: "blue", shape: "dot", text: "registruji…" });
// nová zpráva: z formuláře se dál nepřenáší nic jiného
return gw.cloudRequest(env.get("CLOUD_URL"), "POST", "/gateway/register", { registrationCode: code }, null);

// Výsledek registrace: token gateway trvale uloží do lokální databáze dřív, než začne běžná komunikace.
// Token se nedostane do dashboardu, logů ani fronty dat.
const gw = global.get("gw");
const S = global.get("state");
const cls = gw.classifyResponse(msg.statusCode, msg.payload, msg.headers ?? {});
if (cls.kind !== "ok") {
  S.registration = {
    ok: false,
    message: cls.kind === "auth" ? "neplatný, prošlý nebo už použitý kód – v aplikaci vytvořte novou registraci" : `chyba: ${cls.reason ?? cls.kind}`,
  };
  node.status({ fill: "red", shape: "ring", text: "registrace selhala" });
  return null;
}
const p = msg.payload;
S.identity = { gatewayId: p.gatewayId, roomId: p.roomId, token: p.accessToken };
S.registration = { ok: true, message: `registrováno: gateway ${p.gatewayId}` };
node.status({ fill: "green", shape: "dot", text: `gateway ${p.gatewayId}` });
return { topic: gw.transaction([gw.kvUpsertSql("identity", S.identity, Date.now())]) };

// Po uložení identity: stáhnout konfiguraci, poslat heartbeat a spustit odesílání nashromážděných dat.
// Výstupy: 1 konfigurace, 2 heartbeat, 3 odesílače
return [{ payload: "registered" }, { payload: "registered" }, [{ payload: "event" }, { payload: "measurement" }]];

// Každou hodinu: retence. Cloudem potvrzená data po 24 h (diagnostika ze stejného herního dne),
// potvrzené povely po 7 dnech (aby se povel neprovedl dvakrát). Neodeslaná data a karanténa zůstávají.
const gw = global.get("gw");
const now = Date.now();
msg.topic = gw.transaction([
  `DELETE FROM outbox WHERE state = 'confirmed' AND confirmedAt < ${gw.lit(now - 24 * 3600 * 1000)}`,
  `DELETE FROM command_log WHERE state = 'confirmed' AND confirmedAt < ${gw.lit(now - 7 * 24 * 3600 * 1000)}`,
]);
return msg;

// Chyba z libovolného uzlu (catch) → seznam posledních chyb na dashboardu.
const gw = global.get("gw");
const S = global.get("state");
const source = msg.error?.source?.name || msg.error?.source?.type || "flow";
gw.pushError(S, source, msg.error?.message ?? "neznámá chyba");
return null;

// Každých 5 s: počty položek fronty podle stavu pro dashboard.
msg.topic = "SELECT kind, state, count(*) AS n, min(createdAt) AS oldest FROM outbox GROUP BY kind, state";
msg.payload = [];
return msg;

// Texty pro dashboard. Výstupy: 1 cloud, 2 identita, 3 hra, 4 nody a teplota, 5 fronta, 6 poslední chyby,
// 7 rozšíření
const gw = global.get("gw");
const S = global.get("state");
const rows = msg.payload ?? [];
const now = Date.now();
const count = (...states) => rows.filter((r) => states.includes(r.state)).reduce((sum, r) => sum + r.n, 0);
const waiting = rows.filter((r) => ["pending", "waitingMapping", "inFlight"].includes(r.state));
const oldest = waiting.length ? Math.min(...waiting.map((r) => r.oldest)) : null;
const age = (ms) => (ms < 60000 ? `${Math.round(ms / 1000)} s` : ms < 3600000 ? `${Math.round(ms / 60000)} min` : `${Math.round(ms / 3600000)} h`);

const cloud = !S.identity ? "neregistrovaná"
  : `${S.cloud.online ? "online" : "offline"}${S.cloud.lastContactAt ? `, kontakt ${S.cloud.lastContactAt.slice(11, 19)} UTC` : ""}${S.cloud.alarm ? ` – ${S.cloud.alarm}` : ""}`;
const identity = S.identity ? `gateway ${S.identity.gatewayId}, místnost ${S.identity.roomId}` : (S.registration?.message ?? "zadejte registrační kód z webové aplikace");
const solved = S.game ? S.game.puzzles.filter((p) => p.state === "solved").length : 0;
const game = `${S.game ? `${S.game.state}, vyřešeno ${solved}/${S.game.puzzles.length}` : "žádná hra"} · revize konfigurace ${S.config?.scenario?.revision ?? "–"}`;
const nodes = Object.entries(S.nodes).map(([id, n]) => {
  const online = now - n.lastSeen <= gw.NODE_OFFLINE_MS;
  return `${id}: ${online ? "online" : "offline"}, zařízení ${n.devices.length}${n.badDevices.length ? `, vadné: ${n.badDevices.join(", ")}` : ""}`;
}).join(" · ") || "žádný node";
const temperature = S.lastTemperature ? ` · teplota ${S.lastTemperature.value} °C` : "";
const queue = `čeká ${count("pending", "waitingMapping", "inFlight")} (bez mapování ${count("waitingMapping")})` +
  `${oldest ? `, nejstarší ${age(now - oldest)}` : ""} · potvrzeno ${count("confirmed")} · karanténa ${count("quarantined")}`;
const errors = S.errors.slice(0, 5).map((e) => `${e.at.slice(11, 19)} ${e.source}: ${e.message}`).join(" | ") || "žádné";

// Rozšíření: poslední vstup klávesnice a enkodéru, aktuální text LCD
const inputLabel = { key: "klávesa", code: "kód", turn: "poloha" };
const inputs = Object.entries(S.inputs ?? {}).map(([hwId, i]) => `${hwId}: ${inputLabel[i.e] ?? i.e} ${i.v} (${i.at.slice(11, 19)})`);
const displays = Object.entries(S.displays ?? {}).map(([hwId, lines]) => `${hwId}: „${lines[0]}“ / „${lines[1]}“`);
const extensions = [...inputs, ...displays].join(" · ") || "žádná data (node bez rozšíření?)";

return [{ payload: cloud }, { payload: identity }, { payload: game }, { payload: nodes + temperature }, { payload: queue }, { payload: errors }, { payload: extensions }];

// Tlačítko na dashboardu: po odstranění příčiny vrátí záznamy z karantény k odeslání (obsah se nemění).
const gw = global.get("gw");
msg.topic = gw.transaction(["UPDATE outbox SET state = 'pending', nextAttemptAt = 0, attempts = 0 WHERE state = 'quarantined'"]);
return msg;

// Ruční text na LCD z dashboardu. Povel jde na první online displej a text se uloží pro obnovu
// po restartu nodu. Ukládá se jen v paměti, restart gateway ho neobnoví.
// Vstup: formulář { l1, l2 }. Výstup: povel pro sériovou frontu.
const gw = global.get("gw");
const S = global.get("state");
const now = Date.now();

const display = Object.values(S.nodes)
  .filter((n) => now - n.lastSeen <= gw.NODE_OFFLINE_MS)
  .flatMap((n) => n.devices ?? [])
  .find((d) => d.type === "display");
if (!display) {
  gw.pushError(S, "LCD", "žádný online node s displejem (firmware s ENABLE_EXTENSIONS = 1?)");
  node.status({ fill: "red", shape: "ring", text: "bez displeje" });
  return null;
}

const cmd = gw.lcdCommand(display.id, [msg.payload?.l1, msg.payload?.l2]);
(S.displays ??= {})[display.id] = [cmd.l1, cmd.l2];
node.status({ fill: "green", shape: "dot", text: `${display.id}: ${cmd.l1} / ${cmd.l2}` });
return { topic: "send", payload: cmd };

// Chyba z libovolného uzlu (catch) → seznam posledních chyb na dashboardu.
const gw = global.get("gw");
const S = global.get("state");
const source = msg.error?.source?.name || msg.error?.source?.type || "flow";
gw.pushError(S, source, msg.error?.message ?? "neznámá chyba");
return null;
